'use strict';
async function authorizeExport(){if(currentUser.role!=='supervisor'){toast('只有主管可以匯出');return false;}try{const r=await apiFetch('/api/export-access');if(!r.ok)throw Error('只有主管可以匯出，請確認目前權限');return true;}catch(e){toast(e.message||'無法確認匯出權限');return false;}}
async function loadWelderOptions(shipment){const select=$('#shipment-welder'),message=$('#welder-message');if(!select)return;select.disabled=true;message.textContent='正在讀取員工…';try{const r=await apiFetch('/api/employee-options'),data=await r.json();if(!r.ok||!Array.isArray(data.items))throw Error('員工名單讀取失敗，請重新開啟紀錄重試');if(!select.isConnected)return;const list=data.items.map(e=>({id:String(e.id),name:e.name}));if(shipment.welderId&&!list.some(e=>e.id===shipment.welderId))list.push({id:shipment.welderId,name:shipment.welderName||'原紀錄人員'});select.innerHTML='<option value="" data-name="">'+pe('chooseWelder')+'</option>'+list.map(e=>'<option value="'+esc(e.id)+'" data-name="'+esc(e.name)+'">'+esc(e.name)+'</option>').join('');select.value=shipment.welderId||'';select.disabled=!platingEditAllowed();message.textContent='';}catch(e){if(select.isConnected)message.textContent=e.message;}}
function platingLedgerRows(){return platingProjects().flatMap(p=>(p.shipments||[]).map(s=>({p,s,status:platingStatus(s),totals:platingTotals(s.groups)}))).sort((a,b)=>(a.status==='completed')-(b.status==='completed')||b.s.sent.localeCompare(a.s.sent)||a.p.name.localeCompare(b.p.name)||b.s.number-a.s.number);}
let ledgerFilter='all',ledgerQuery='';
function openPlatingLedger(){
 const rows=platingLedgerRows();platingModal(pe('ledger'),'<div class="ledger-tools"><div id="ledger-filters"></div><input id="ledger-search" placeholder="'+pe('search')+'" aria-label="'+pe('search')+'" value="'+esc(ledgerQuery)+'">'+(currentUser.role==='supervisor'?'<button type="button" id="ledger-export">'+pe('exportTable')+'</button>':'')+'</div><div class="ledger-scroll"><table class="ledger-table"><thead><tr>'+['name','number','vendor','sent','returned','groups','status','welder'].map(k=>'<th>'+pe(k)+'</th>').join('')+'</tr></thead><tbody id="ledger-rows"></tbody></table></div><p id="ledger-empty"></p>','',null);
 let shown=[];function draw(){shown=rows.filter(r=>(ledgerFilter==='all'||r.status===ledgerFilter)&&r.p.name.toLowerCase().includes(ledgerQuery.trim().toLowerCase()));$('#ledger-filters').innerHTML=['all','sending','completed'].map(k=>'<button type="button" data-ledger-filter="'+k+'" class="'+(ledgerFilter===k?'selected':'')+'">'+pe(k)+' '+rows.filter(r=>k==='all'||r.status===k).length+'</button>').join('');$('#ledger-rows').innerHTML=shown.map((r,i)=>'<tr data-ledger-row="'+i+'" tabindex="0"><td><button type="button" class="ledger-case">'+esc(r.p.name)+'</button></td><td>'+esc(platingCount(r.s))+'</td><td>'+esc(r.s.vendor)+'</td><td>'+esc(platingDate(r.s.sent))+'</td><td>'+esc(r.s.returned?platingDate(r.s.returned):'—')+'</td><td>'+r.totals.sets+'組／'+r.totals.pieces+'片</td><td><span class="ledger-status '+r.status+'">'+pe(r.status)+'</span></td><td>'+esc(r.s.welderName||'—')+'</td></tr>').join('');$('#ledger-empty').textContent=shown.length?'':pt('empty');document.querySelectorAll('[data-ledger-filter]').forEach(b=>b.onclick=()=>{ledgerFilter=b.dataset.ledgerFilter;draw();});document.querySelectorAll('[data-ledger-row]').forEach(tr=>{const open=()=>{const r=shown[Number(tr.dataset.ledgerRow)];editPlatingShipment(r.p.id,r.s.id);const back=document.createElement('button');back.type='button';back.className='small';back.textContent='← '+pt('ledger');back.onclick=async()=>{if(typeof shipmentGuard44==='function'&&shipmentGuard44()&&!await confirmAction('有尚未儲存的送鍍內容，確定放棄並離開？'))return;openPlatingLedger();};$('#plating-back').after(back);};tr.onclick=open;tr.onkeydown=e=>{if(e.target===tr&&(e.key==='Enter'||e.key===' ')){e.preventDefault();open();}};});}
 $('#ledger-search').oninput=e=>{ledgerQuery=e.target.value;draw();};$('#ledger-export')?.addEventListener('click',async()=>{if(!await authorizeExport())return;const data=[['案名','次數','廠商','寄出日期','完成回貨日','治具組數','環片片數','狀態','焊接人員'],...shown.map(r=>[r.p.name,r.s.number,r.s.vendor,platingDate(r.s.sent),r.s.returned?platingDate(r.s.returned):'',r.totals.sets,r.totals.pieces,pt(r.status),r.s.welderName||''])];await downloadBlob(new Blob([platingCsv(data)],{type:'text/csv;charset=utf-8'}),'電鍍出入貨紀錄.csv');});draw();
}
